const DINOS={"Adynomosaurus":{"n":"Adynomosaurus","u":"https://dinosaurpictures.org/Adynomosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Tremp Formation (Espagne)","t":"Adynomosaurus est un genre fossile de dinosaures Hadrosauridae, classé dans la sous-famille des Lambeosaurinae. Ses fossiles ont été découverts dans le nord-est de l’Espagne, dans les strates de la formation de Conques, datée du Maastrichtien inférieur, il y a environ 70 Ma.","i":"data:image/webp;base64,","c":""},"Acostasaurus":{"n":"Acostasaurus","u":"https://dinosaurpictures.org/Acostasaurus-pictures","r":"","p":"","z":"","g":"","t":"Acostasaurus est un genre fossile de plésiosaures dans la famille des Pliosauridae.","i":"data:image/webp;base64,","c":""},"Anhuilong":{"n":"Anhuilong","u":"https://dinosaurpictures.org/Anhuilong-pictures","r":"","p":"Unknown","z":"Asie","g":"Anhui (China)","t":"Anhuilong est un genre fossile de dinosaures Mamenchisauridae connu dans la formation de Hongqin, du Jurassique moyen, dans la province de l'Anhui, en Chine. Le genre contient une seule espèce, Anhuilong diboensis.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Aepisaurus":{"n":"Aepisaurus","u":"https://dinosaurpictures.org/Aepisaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Vaucluse (France)","t":"Aepisaurus est un genre fossile de dinosaures qui vivait au Crétacé inférieur (Albien), soit environ il y a de 113 et 100,5 Ma.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Actiosaurus":{"n":"Actiosaurus","u":"https://dinosaurpictures.org/Actiosaurus-pictures","r":"","p":"","z":"","g":"","t":"Actiosaurus est un genre fossile d'animal originellement décrit par Henri Émile Sauvage (1842-1917) en 1883 comme un dinosaure.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Aletopelta":{"n":"Aletopelta","u":"https://dinosaurpictures.org/Aletopelta-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Nord","g":"California","t":"Aletopelta est un genre fossile de dinosaure ornithischien herbivore le l'infra-ordre des ankylosauriens ayant vécu en Californie du Sud, au Crétacé supérieur, il y a environ 84 à 72 millions d'années.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Ampelosaurus":{"n":"Ampelosaurus","u":"https://dinosaurpictures.org/Ampelosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Castile-La Mancha (Spain) , Barcelona (Spain) and Aude (France)","t":"Ampelosaurus est un genre de dinosaures sauropodes de la famille des Titanosauridae découvert dans le Crétacé supérieur du sud de la France. Ses restes ont été découverts près du village de Campagne-sur-Aude dans le département de l’Aude en région Occitanie.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Aeolosaurus":{"n":"Aeolosaurus","u":"https://dinosaurpictures.org/Aeolosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Sud","g":"Argentine, Argentine et São Paulo (Brésil)","t":"Aeolosaurus est un genre fossile de dinosaures sauropodes commun dans l’hémisphère sud à la fin du Crétacé supérieur, soit il y a environ entre 80 et 70 Ma. Il ressemblait au titanosaure, mais avait de longues vertèbres caudales et une épine recourbée vers l’avant.","i":"data:image/webp;base64,","c":""},"Antarctosaurus":{"n":"Antarctosaurus","u":"https://dinosaurpictures.org/Antarctosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Sud","g":"Argentine, Minas Gerais (Brésil) et Río Negro (Uruguay)","t":"Antarctosaurus est un genre fossile mal connu de dinosaures sauropodes herbivores, un titanosaure basal ayant vécu en Amérique du Sud à la fin du Crétacé, soit il y a environ entre 83,6 et 66,0 millions d'années. Ce genre Antarctosaurus est resté monotypique, avec une seule espèce fossile valide l'espèce type Antarctosaurus…","i":"data:image/webp;base64,","c":""},"Arambourgiania":{"n":"Arambourgiania","u":"https://dinosaurpictures.org/Arambourgiania-pictures","r":"","p":"","z":"","g":"","t":"Arambourgiania est un genre fossile de ptérosaures de la fin du Crétacé supérieur (Maastrichtien) ayant vécu en Jordanie. Il était l'un des plus grands représentants de ce groupe.","i":"data:image/webp;base64,","c":""},"Astrodon":{"n":"Astrodon","u":"https://dinosaurpictures.org/Astrodon-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Nord","g":"Texas, Tahoua (Niger) et Virginia","t":"Astrodon était un genre fossile obsolète de sauropode du Crétacé inférieur qui vivait il y a environ 135 Ma. Son nom signifie « à la dent en étoile ».","i":"data:image/webp;base64,","c":""},"Arcovenator":{"n":"Arcovenator","u":"https://dinosaurpictures.org/Arcovenator-pictures","r":"carnivore","p":"Crétacé","z":"Europe","g":"Castile et León (Espagne)","t":"Arcovenator est un genre fossile de dinosaures théropodes abélisauridés, qui vivait en Europe au Crétacé supérieur.","i":"data:image/webp;base64,","c":""},"Arenysaurus":{"n":"Arenysaurus","u":"https://dinosaurpictures.org/Arenysaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Aragon (Espagne)","t":"Arenysaurus est un genre fossile de dinosaures ornithopodes de la famille des hadrosauridés et de la sous-famille des lambéosaurinés. Il a vécu tout à la fin du Crétacé supérieur où il figure parmi les derniers dinosaures qui existaient encore avant l'Extinction Crétacé-Tertiaire, il y a 66 Ma.","i":"data:image/webp;base64,","c":""},"Atlascopcosaurus":{"n":"Atlascopcosaurus","u":"https://dinosaurpictures.org/Atlascopcosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Australie","g":"Victoria (australia) et Victoria (australia)","t":"Atlascopcosaurus Rich et Vickers-Rich 1989, ou Lézard de l'Atlas Copco est un genre fossile de dinosaures herbivores appartenant à l'ordre des ornithischiens, au sous-ordre des ornithopodes et à la famille des hypsilophodontidés. Il a vécu en Australie vers la fin du Crétacé inférieur entre la fin de l'Aptien et le début de…","i":"data:image/webp;base64,","c":""},"Blasisaurus":{"n":"Blasisaurus","u":"https://dinosaurpictures.org/Blasisaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Aragon (Espagne)","t":"Blasisaurus est un genre fossile de dinosaures ornithopodes de la famille des hadrosauridés et de la sous-famille des lambéosaurinés. Il a vécu tout à la fin du Crétacé supérieur où il figure parmi les derniers dinosaures qui existaient encore avant l'Extinction Crétacé-Tertiaire, il y a 66 Ma.","i":"data:image/webp;base64,","c":""},"Brachauchenius":{"n":"Brachauchenius","u":"https://dinosaurpictures.org/Brachauchenius-pictures","r":"","p":"","z":"","g":"","t":"Brachauchenius est un genre fossile de pliosaures ayant vécu durant le Crétacé. Une seule espèce est connue, Brachauchenius lucasi, décrite en 1903 à partir de fossiles découverts au Kansas.","i":"data:image/webp;base64,","c":""},"Bolong":{"n":"Bolong","u":"https://dinosaurpictures.org/Bolong-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Liaoning (Chine) et Guangdong (Chine)","t":"Le bolong est un chenal d'eau salée, caractéristique des zones côtières du Sénégal ou de Gambie, proches d'estuaires.","i":"data:image/webp;base64,","c":""},"Callawayasaurus":{"n":"Callawayasaurus","u":"https://dinosaurpictures.org/Callawayasaurus-pictures","r":"","p":"","z":"","g":"","t":"Callawayasaurus est un genre fossile de plésiosaure de la famille des Elasmosauridae. Il n'est représenté que par son espèce type, Callawayasaurus colombiensis.","i":"data:image/webp;base64,","c":""},"Cimoliasaurus":{"n":"Cimoliasaurus","u":"https://dinosaurpictures.org/Cimoliasaurus-pictures","r":"","p":"","z":"","g":"","t":"Cimoliasaurus est un genre fossile de plésiosaures du New Jersey (États-Unis), qui a vécu pendant le Crétacé supérieur. Il pouvait atteindre une taille avoisinant les 5 mètres pour un poids de près d'une tonne.","i":"data:image/webp;base64,","c":""},"Colymbosaurus":{"n":"Colymbosaurus","u":"https://dinosaurpictures.org/Colymbosaurus-pictures","r":"","p":"","z":"","g":"","t":"Colymbosaurus est un genre fossile de plésiosaures de la super-famille des Plesiosauroidea et de la famille des Cryptoclididae.","i":"data:image/webp;base64,","c":""},"Dacentrurus":{"n":"Dacentrurus","u":"https://dinosaurpictures.org/Dacentrurus-pictures","r":"herbivore","p":"Jurassique","z":"Europe","g":"Valencian Community (Espagne), Metropolitan France (France) et Alentejo (Portugal)","t":"Dacentrurus est un genre fossile de dinosaures herbivores de l'infra-ordre des stégosauriens qui vécut à la fin du Jurassique supérieur, il y a environ 155 à 150 millions d'années (Ma).","i":"data:image/webp;base64,","c":""},"Diluvicursor":{"n":"Diluvicursor","u":"https://dinosaurpictures.org/Diluvicursor-pictures","r":"herbivore","p":"Crétacé inférieur","z":"Australie","g":"Victoria (australia)","t":"Diluvicursor est un genre fossile de dinosaures ornithischiens du clade des Elasmaria. On n'en connaît que l'espèce Diluvicursor pickeringi décrite en 2018 qui vivait en Australie lors du Crétacé supérieur (Albien) il y a environ 113 millions d'années.","i":"data:image/webp;base64,","c":"Herne MC, Tait AM, Weisbecker V, Hall M, Nair JP, Cleeland M, Salisbur · CC BY-SA 4.0"},"Draconyx":{"n":"Draconyx","u":"https://dinosaurpictures.org/Draconyx-pictures","r":"herbivore","p":"Jurassique","z":"Europe","g":"Centro (Portugal) et Área Metropolitana de Lisboa (Portugal)","t":"Draconyx est un genre fossile de dinosaures ornithischiens ornithopodes de la fin du Jurassique (Tithonien). Cet herbivore voisin des iguanodons vivait dans ce qui est maintenant le Portugal.","i":"data:image/webp;base64,","c":""},"Carcharodontosaurus":{"n":"Carcharodontosaurus","u":"https://dinosaurpictures.org/Carcharodontosaurus-pictures","r":"carnivore","p":"Crétacé","z":"Afrique","g":"Illizi (Algeria), Tataouine (Tunisia) et El Bayadh (Algeria)","t":"Carcharodontosaurus est un genre fossile de grands dinosaures théropodes carnivores ayant vécu durant l'étage Cénomanien du Crétacé supérieur, dans ce qui est aujourd'hui l'Afrique du Nord. Le taxon est premièrement décrit en 1925 par Charles Depéret et Justin Savornin sous le nom de Megalosaurus saharicus sur la base de deux…","i":"data:image/webp;base64,","c":""},"Dracovenator":{"n":"Dracovenator","u":"https://dinosaurpictures.org/Dracovenator-pictures","r":"carnivore","p":"Jurassique","z":"Afrique","g":"Free State (Afrique du Sud) et North West (Afrique du Sud)","t":"Dracovenator est un genre fossile de dinosaures théropodes du Jurassique inférieur retrouvé en Afrique du Sud. Sa taille est estimée entre 5,5 et 7 mètres de longueur pour une masse maximale de 400 kilogrammes.","i":"data:image/webp;base64,","c":""},"Dromicosaurus":{"n":"Dromicosaurus","u":"https://dinosaurpictures.org/Dromicosaurus-pictures","r":"herbivore","p":"Jurassique inférieur","z":"Afrique","g":"North West (Afrique du Sud)","t":"Massospondylus est un genre fossile de dinosaures saurischiens herbivores au long cou, du clade des Plateosauria et de celui des Massopoda, et de famille des Massospondylidae. Il a été découvert dans le sud de l'Afrique, où il a vécu au Jurassique inférieur, soit il y a environ entre 201,4 à 184,2 millions d'années.","i":"data:image/webp;base64,","c":""},"Edmontonia":{"n":"Edmontonia","u":"https://dinosaurpictures.org/Edmontonia-pictures","r":"herbivore","p":"Crétacé supérieur","z":"Amérique du Nord","g":"Coahuila (Mexique), Montana et South Dakota","t":"Edmontonia est un genre fossile de dinosaures ornithischiens herbivores, un ankylosaurien de la famille des nodosauridés. Il a vécu dans ce qui est maintenant l'Amérique du nord, où il est connu par de nombreux restes fossiles de l'Alaska jusqu'au Texas.","i":"data:image/webp;base64,","c":""},"Elaphrosaurus":{"n":"Elaphrosaurus","u":"https://dinosaurpictures.org/Elaphrosaurus-pictures","r":"carnivore","p":"Jurassique","z":"Afrique","g":"Illizi (Algeria), Tataouine (Tunisia) et Béchar (Algeria)","t":"Elaphrosaurus, qui signifie \"reptile léger\", vivait en Tanzanie il y a 150 Ma. Ce genre Elaphrosaurus est resté monotypique et la seule espèce fossile connue est l'espèce Elaphrosaurus bambergi.","i":"data:image/webp;base64,","c":"FunkMonk · CC BY-SA 3.0"},"Eoraptor":{"n":"Eoraptor","u":"https://dinosaurpictures.org/Eoraptor-pictures","r":"omnivore","p":"Trias","z":"Amérique du Sud","g":"Argentine","t":"Eoraptor est un genre fossile de petit dinosaure sauropodomorphe basaux, qui a vécu en Argentine pendant le Trias supérieur, entre 230 et 225 millions d'années avant le présent.","i":"data:image/webp;base64,","c":""},"Dubreuillosaurus":{"n":"Dubreuillosaurus","u":"https://dinosaurpictures.org/Dubreuillosaurus-pictures","r":"carnivore","p":"Jurassique","z":"Europe","g":"Normandy (France)","t":"Dubreuillosaurus est un genre fossile de dinosaures carnivores, un théropode de la famille des mégalosauridés, qui vivait au Jurassique moyen durant le Bathonien. Ces fossiles ont été trouvés en France, en Normandie, dans le département du Calvados, plus précisément dans la formation du calcaire de Caen datée de la base du…","i":"data:image/webp;base64,","c":""},"Erectopus":{"n":"Erectopus","u":"https://dinosaurpictures.org/Erectopus-pictures","r":"carnivore","p":"Crétacé","z":"Europe","g":"Grand Est (France), Grand Est (France) et Portugal","t":"Erectopus est un genre fossile de dinosaures théropodes de la super-famille des allosauroïdes, qui a vécu au Crétacé inférieur et au tout début du Crétacé supérieur. Ses restes fossiles ont tout d'abord été trouvés dans l'est de la France dans des sédiments phosphatés datés de l'Albien inférieur.","i":"data:image/webp;base64,","c":""},"Euronychodon":{"n":"Euronychodon","u":"https://dinosaurpictures.org/Euronychodon-pictures","r":"carnivore","p":"Crétacé","z":"Europe","g":"Centro (Portugal), Castile-La Mancha (Espagne) et Rioja (Espagne)","t":"Euronychodon est un genre fossile de dinosaures ayant vécu au cours du Crétacé supérieur, du Turonien au Maastrichtien, c'est-à-dire il y a environ entre 94 et 66 Ma.","i":"data:image/webp;base64,","c":""},"Fresnosaurus":{"n":"Fresnosaurus","u":"https://dinosaurpictures.org/Fresnosaurus-pictures","r":"","p":"","z":"","g":"","t":"Fresnosaurus est un genre fossile de plésiosaures dans la famille des Elasmosauridae.","i":"data:image/webp;base64,","c":"LancianIdolatry · CC0"},"Fylax":{"n":"Fylax","u":"https://dinosaurpictures.org/Fylax-pictures","r":"herbivore","p":"Crétacé supérieur","z":"Europe","g":"Catalonia (Espagne)","t":"Fylax est un genre éteint de dinosaures hadrosauroïdés ayant vécu durant le Maastrichtien supérieur en Espagne. Il n‘est connu que par un dentaire gauche presque complet (IPS-36338) collecté au début des années 1990 dans les strates de la Formation de Figuerola affleurant sur le flanc sud du synclinal d’Àger, près du village de…","i":"data:image/webp;base64,","c":""},"Grallator":{"n":"Grallator","u":"https://dinosaurpictures.org/Grallator-pictures","r":"carnivore","p":"Crétacé","z":"Australie","g":"Chongqing (Chine), England (Royaume-Uni) et Gard (France)","t":"Grallator est un ichnotaxon, un genre attribué à des empreintes de pas laissées sur des pistes en plusieurs endroits d'Europe ou en Amérique (Nouvelle-Écosse). Elles ont sans doute été faites par un saurien, probablement déjà dinosaure, ayant vécu à la fin du Trias, probable herbivore qui se dressait sur ses deux pattes arrière.","i":"data:image/webp;base64,","c":""},"Fukuisaurus":{"n":"Fukuisaurus","u":"https://dinosaurpictures.org/Fukuisaurus-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Fukui Prefecture (Japon)","t":"Fukuisaurus est un genre fossile de dinosaures ornithischiens, un Hadrosauroidea basal du Crétacé inférieur retrouvé au Japon.","i":"data:image/webp;base64,","c":""},"Huangshanlong":{"n":"Huangshanlong","u":"https://dinosaurpictures.org/Huangshanlong-pictures","r":"","p":"Unknown","z":"Asie","g":"Anhui (Chine)","t":"Huangshanlong est un genre fossile de dinosaures Mamenchisauridae originaire de la province d'Anhui en Chine. Il contient une seule espèce, Huangshanlong anhuiensis.","i":"data:image/webp;base64,","c":""},"Hypselosaurus":{"n":"Hypselosaurus","u":"https://dinosaurpictures.org/Hypselosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Aragon (Espagne), Barcelona (Espagne) et Castile-La Mancha (Espagne)","t":"Hypselosaurus est un titanosaure d'environ 27 mètres de long retrouvé sur le territoire de l'actuelle Europe. Il aurait vécu lors du Crétacé supérieur (Maastrichtien).","i":"data:image/webp;base64,","c":""},"Galleonosaurus":{"n":"Galleonosaurus","u":"https://dinosaurpictures.org/Galleonosaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Hypnovenator":{"n":"Hypnovenator","u":"https://dinosaurpictures.org/Hypnovenator-pictures","r":"carnivore","p":"Crétacé inférieur","z":"Asie","g":"Japon","t":"Hypnovenator est un genre fossile de Dinosauria paraviens de la famille des Troodontidae ayant vécu au Crétacé inférieur, plus précisément lors de la période de l'Albien entre 112 et 106 millions d'années. Et a vécu au Japon ou il a été découvert dans la formation de Ohyamashimo.","i":"data:image/webp;base64,","c":""},"Herrerasaurus":{"n":"Herrerasaurus","u":"https://dinosaurpictures.org/Herrerasaurus-pictures","r":"carnivore","p":"Trias","z":"Amérique du Sud","g":"Argentina and Argentina","t":"Herrerasaurus est un genre fossile de dinosaures carnivores qui ont vécu au cours du Trias supérieur, il y a environ de 230 à 220 millions d’années en Argentine. Apparenté aux théropodes, ou considéré comme un saurischien basal, Herrerasaurus en est un représentant très primitif, précédant de 75 millions d’années l’apparition…","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Huehuecanauhtlus":{"n":"Huehuecanauhtlus","u":"https://dinosaurpictures.org/Huehuecanauhtlus-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Nord","g":"Mexico (Mexico)","t":"Huehuecanauhtlus est un genre fossile de dinosaures Hadrosauroidea connu du Crétacé supérieur du Michoacán, dans l'ouest du Mexique. Il contient une seule espèce, Huehuecanauhtlus tiquichensis.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Gresslyosaurus":{"n":"Gresslyosaurus","u":"https://dinosaurpictures.org/Gresslyosaurus-pictures","r":"herbivore","p":"Trias supérieur","z":"Europe","g":"Schaffhausen (Suisse), Bourgogne – Franche-Comté (France) et Baden-Württemberg (Allemagne)","t":"Plateosaurus est un genre fossile de dinosaures sauropodomorphes herbivores basaux, de la famille des Plateosauridae. Ils sont apparus au Trias supérieur il y a environ 214 millions d'années et ont vécu dans ce qui est maintenant l'Europe.","i":"data:image/webp;base64,","c":""},"Iguanodon":{"n":"Iguanodon","u":"https://dinosaurpictures.org/Iguanodon-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Arad (Roumanie), Valencian Community (Espagne) et Grand Est (France)","t":"Iguanodon est un genre fossile de dinosaures de l'ordre des ornithischiens, c'est-à-dire des dinosaures caractérisés par un bassin semblable à celui d'un oiseau, du sous-ordre des ornithopodes.","i":"data:image/webp;base64,","c":""},"Inabtanin":{"n":"Inabtanin","u":"https://dinosaurpictures.org/Inabtanin-pictures","r":"","p":"","z":"","g":"","t":"Inabtanin est un genre fossile de ptérosaures dans le clade des Azhdarchoidea dans la super-famille des Ornithocheiroidea. Ce genre Inabtanin est monotypique avec une seule espèce fossile Inabtanin alarabia","i":"data:image/webp;base64,","c":""},"Laplatasaurus":{"n":"Laplatasaurus","u":"https://dinosaurpictures.org/Laplatasaurus-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Sud","g":"Argentine, Argentine et Río Negro (Uruguay)","t":"Laplatasaurus est un genre fossile de dinosaures sauropodes, un titanosaure découvert en Amérique du Sud et ayant vécu lors du Crétacé supérieur. Ce genre Laplatasaurus est resté monotypique et la seule espèce fossile connue est Laplatasaurus araukanicus.","i":"data:image/webp;base64,","c":""},"Leaellynasaura":{"n":"Leaellynasaura","u":"https://dinosaurpictures.org/Leaellynasaura-pictures","r":"herbivore","p":"Crétacé","z":"Australie","g":"Victoria (australia) et Victoria (australia)","t":"Leaellynasaura est un genre fossile de dinosaures ornithopodes de la famille des hypsilophodontidés, ayant vécu en Australie à la fin du Crétacé inférieur il y a environ 115 Ma.","i":"data:image/webp;base64,","c":""},"Lexovisaurus":{"n":"Lexovisaurus","u":"https://dinosaurpictures.org/Lexovisaurus-pictures","r":"herbivore","p":"Jurassique","z":"Europe","g":"England (Royaume-Uni), North Rhine-Westphalia (Allemagne) et Pays de la Loire (France)","t":"Lexovisaurus est un genre fossile obsolète de dinosaures herbivores de l'infra-ordre des stégosauriens découvert dans le Jurassique moyen, au Callovien moyen, soit il y a environ 165 Ma. L'existence de genre est aujourd'hui remise en question.","i":"data:image/webp;base64,","c":""},"Lophostropheus":{"n":"Lophostropheus","u":"https://dinosaurpictures.org/Lophostropheus-pictures","r":"carnivore","p":"","z":"Europe","g":"Normandy (France)","t":"Lophostropheus est un genre fossile de dinosaures carnivores dont les restes fossiles se trouvent dans des couches allant du Trias supérieur au Jurassique inférieur, en Basse-Normandie dans la Manche (France). Ce genre est resté monotypique et une seule espèce fossile est connue l'espèce type Lophostropheus airelensis.","i":"","c":""},"Losillasaurus":{"n":"Losillasaurus","u":"https://dinosaurpictures.org/Losillasaurus-pictures","r":"herbivore","p":"","z":"Europe","g":"","t":"Losillasaurus est un genre fossile de grands dinosaures sauropodes herbivores, appartenant au clade des Turiasauria, un taxon d'eusauropodes primitifs, défini en même temps que Turiasaurus.","i":"data:image/webp;base64,","c":""},"Mantellisaurus":{"n":"Mantellisaurus","u":"https://dinosaurpictures.org/Mantellisaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"North Rhine-Westphalia (Allemagne), Hauts-de-France (France) et Aragon (Espagne)","t":"Mantellisaurus est un genre fossile de dinosaures de l'ordre des ornithischiens, c'est-à-dire des dinosaures caractérisés par un bassin semblable à celui d'un oiseau. Mantellisaurus a vécu en Europe durant la première moitié du Crétacé inférieur, soit il y a environ entre 145 et 122 Ma.","i":"data:image/webp;base64,","c":"Steveoc 86 · CC BY-SA 3.0"},"Mauisaurus":{"n":"Mauisaurus","u":"https://dinosaurpictures.org/Mauisaurus-pictures","r":"","p":"","z":"","g":"","t":"Mauisaurus est un genre fossile de Plesiosauroidea de la famille des Elasmosauridae. Il vivait au Crétacé supérieur dans les eaux de l’actuelle Nouvelle-Zélande.","i":"data:image/webp;base64,","c":""},"Megalosaurus":{"n":"Megalosaurus","u":"https://dinosaurpictures.org/Megalosaurus-pictures","r":"carnivore","p":"Jurassique","z":"Europe","g":"Centro (Portugal), England (Royaume-Uni) et Metropolitan France (France)","t":"Megalosaurus est un genre fossile de dinosaures de l'ordre des saurischiens, du sous-ordre des théropodes et de la famille des Megalosauridae. Il vécut au Jurassique moyen, sur une période s'étendant d'environ 175 à 164 millions d'années.","i":"data:image/webp;base64,","c":""},"Microcleidus":{"n":"Microcleidus","u":"https://dinosaurpictures.org/Microcleidus-pictures","r":"","p":"","z":"","g":"","t":"Microcleidus est un genre fossile de plésiosaures appartenant à la super-famille des Plesiosauroidea, ayant vécu au cours du Jurassique inférieur. Il fait partie de la famille des Microcleididae, dont il est le genre type.","i":"data:image/webp;base64,","c":""},"Morenosaurus":{"n":"Morenosaurus","u":"https://dinosaurpictures.org/Morenosaurus-pictures","r":"","p":"","z":"","g":"","t":"Morenosaurus est un genre fossile de plésiosaures dans le clade des Weddellonectia de la famille des Elasmosauridae.","i":"data:image/webp;base64,","c":""},"Nanshiungosaurus":{"n":"Nanshiungosaurus","u":"https://dinosaurpictures.org/Nanshiungosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Guangdong (Chine) et Gansu (Chine)","t":"Nanshiungosaurus est un genre fossile de dinosaures théropodes de la famille des thérizinosauridés asiatiques, dont le nom de genre signifie « lézard de Nanxiong ». Il ressemble à un ornithomimidé.","i":"data:image/webp;base64,","c":""},"Neuquensaurus":{"n":"Neuquensaurus","u":"https://dinosaurpictures.org/Neuquensaurus-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Sud","g":"Argentine, Argentine et Río Negro (Uruguay)","t":"Neuquensaurus est un genre de dinosaures sauropodes saltasaurinés qui est apparu durant le Crétacé supérieur, en Argentine et en Uruguay il y a 71 millions d'années. Des fossiles ont été découverts aux alentours de Cinco Saltos, proche de la rivière Neuquén, au cœur de la formation d'Anacleto.","i":"data:image/webp;base64,","c":""},"Normanniasaurus":{"n":"Normanniasaurus","u":"https://dinosaurpictures.org/Normanniasaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Normandy (France)","t":"Normanniasaurus est un genre fossile de dinosaures sauropodes, un titanosaure basal ayant vécu en Europe à la fin du Crétacé inférieur.","i":"","c":""},"Normannognathus":{"n":"Normannognathus","u":"https://dinosaurpictures.org/Normannognathus-pictures","r":"","p":"","z":"","g":"","t":"Normannognathus est un genre fossile de ptérodactyloïdes archaeoptérodactyloïdes appartenant à la famille des gallodactylidés. C'est un ptérosaure, un groupe fossile de « reptiles ailés ».","i":"data:image/webp;base64,","c":""},"Mosasaurus":{"n":"Mosasaurus","u":"https://dinosaurpictures.org/Mosasaurus-pictures","r":"carnivore","p":"Crétacé","z":"Europe and North America","g":"Centre-Loire Valley (France), South Dakota et Nebraska","t":"Mosasaurus est un genre fossile de grands squamates marins de la famille des mosasauridés dont il est le genre type, ayant vécu durant le Crétacé supérieur, entre 82 et 66 millions d'années avant notre ère. Les premiers fossiles de Mosasaurus sont des crânes découverts dans une carrière située près de Maastricht, aux Pays-Bas,…","i":"data:image/webp;base64,","c":""},"Obelignathus":{"n":"Obelignathus","u":"https://dinosaurpictures.org/Obelignathus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Orthomerus":{"n":"Orthomerus","u":"https://dinosaurpictures.org/Orthomerus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Ostromia":{"n":"Ostromia","u":"https://dinosaurpictures.org/Ostromia-pictures","r":"carnivore","p":"Jurassique supérieur","z":"Europe","g":"Riedenburg (Allemagne) et Allemagne (Allemagne)","t":"Ostromia est un genre fossile de petits dinosaures théropodes avialiens de la famille des Anchiornithidae. Ce genre n'est connu que par un seul spécimen, un fossile provenant du calcaire de Solnhofen de Bavière (Allemagne).","i":"data:image/webp;base64,","c":""},"Padillasaurus":{"n":"Padillasaurus","u":"https://dinosaurpictures.org/Padillasaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Paralititan":{"n":"Paralititan","u":"https://dinosaurpictures.org/Paralititan-pictures","r":"herbivore","p":"Crétacé","z":"Afrique","g":"Giza Governorate (Égypte)","t":"Paralititan est un genre fossile de dinosaures sauropodes du groupe des titanosaures, ayant vécu au début du Crétacé supérieur dans ce qui est aujourd'hui l'Égypte. La seule espèce décrite, Paralititan stromeri, a été découverte par Stromer en 1916 et décrite en 2001.","i":"data:image/webp;base64,","c":"Dmitry Bogdanov · CC BY 3.0"},"Pararhabdodon":{"n":"Pararhabdodon","u":"https://dinosaurpictures.org/Pararhabdodon-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Aragon (Espagne) et Catalonia (Espagne)","t":"Pararhabdodon est un genre fossile de dinosaures ornithopodes de la famille des hadrosauridés, classé dans la sous-famille des Lambeosaurinae. Il a été découvert en Espagne dans le bassin de Tremp en Catalogne, où il a vécu à la fin du Crétacé supérieur, il y a environ entre 67 et 66 Ma, juste avant l'extinction massive du…","i":"data:image/webp;base64,","c":""},"Paronychodon":{"n":"Paronychodon","u":"https://dinosaurpictures.org/Paronychodon-pictures","r":"carnivore","p":"Crétacé","z":"Amérique du Nord","g":"Utah, Coahuila (Mexique) et Montana","t":"Paronychodon est un genre fossile de petits dinosaures théropodes paraviens, qui a vécu au cours du Crétacé supérieur, et dont les fossiles sont connus en Amérique du Nord et en Ouzbékistan.","i":"data:image/webp;base64,","c":""},"Peltosaurus":{"n":"Peltosaurus","u":"https://dinosaurpictures.org/Peltosaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Phuwiangosaurus":{"n":"Phuwiangosaurus","u":"https://dinosaurpictures.org/Phuwiangosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Roi Et Province (Thailand), Sakon Nakhon Province (Thailand) et Chaiyaphum Province (Thailand)","t":"Phuwiangosaurus est un genre fossile de dinosaures du Crétacé inférieur. C'était un titanosaure qui vivait dans l'actuelle Thaïlande.","i":"data:image/webp;base64,","c":"Ghedoghedo · CC BY-SA 3.0"},"Plateosaurus":{"n":"Plateosaurus","u":"https://dinosaurpictures.org/Plateosaurus-pictures","r":"herbivore","p":"Trias","z":"Europe","g":"Bavaria (Allemagne), Thuringia (Allemagne) et Greenland","t":"Plateosaurus est un genre fossile de dinosaures sauropodomorphes herbivores basaux, de la famille des Plateosauridae. Ils sont apparus au Trias supérieur il y a environ 214 millions d'années et ont vécu dans ce qui est maintenant l'Europe.","i":"data:image/webp;base64,","c":"No machine-readable author provided. Tbc assumed (based on copyright c · Public domain"},"Plesiosaurus":{"n":"Plesiosaurus","u":"https://dinosaurpictures.org/Plesiosaurus-pictures","r":"","p":"","z":"","g":"","t":"Plesiosaurus est un genre fossile de reptiles marins servant de genre type aux plésiosaures, ayant vécu durant l'étage Sinémurien du Jurassique inférieur dans ce qui est actuellement l'Angleterre. Le taxon est décrit pour la première fois en 1821 par Henry De la Beche et William Conybeare à partir de restes fossiles isolés…","i":"data:image/webp;base64,","c":"the paleobear · CC BY 2.0"},"Pliosaurus":{"n":"Pliosaurus","u":"https://dinosaurpictures.org/Pliosaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"data:image/webp;base64,","c":"Radim Holiš · CC BY-SA 3.0 cz"},"Propanoplosaurus":{"n":"Propanoplosaurus","u":"https://dinosaurpictures.org/Propanoplosaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Quetecsaurus":{"n":"Quetecsaurus","u":"https://dinosaurpictures.org/Quetecsaurus-pictures","r":"herbivore","p":"Crétacé","z":"Amérique du Sud","g":"Argentine","t":"Quetecsaurus est un genre fossile de titanosaures du Crétacé supérieur retrouvé dans la province de Mendoza, en Argentine. L'espèce type et seule espèce fossile est Quetecsaurus rusconii.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Ratchasimasaurus":{"n":"Ratchasimasaurus","u":"https://dinosaurpictures.org/Ratchasimasaurus-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Nakhon Nayok Province (Thailand)","t":"Ratchasimasaurus est un genre fossile de dinosaure ornithopode iguanodontien du Crétacé inférieur, durant l'Aptien, soit il y a environ entre 121,4 et 113,2 millions d'années. Ces fossile ont été trouvés dans la formation Khok Kruat (en), province de Nakhon Ratchasima dans le nord-est de la Thaïlande.","i":"data:image/webp;base64,","c":"Pescov · CC BY-SA 4.0"},"Rhabdodon":{"n":"Rhabdodon","u":"https://dinosaurpictures.org/Rhabdodon-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Roumanie, Catalonia (Espagne) et Barcelona (Espagne)","t":"Rhabdodon est un genre de dinosaures ornithopodes herbivores qui a existé en Europe à la fin du Crétacé supérieur (Maastrichtien) il y a environ 70 millions d'années. Ses fossiles ont été trouvés en Espagne, France, Autriche et Roumanie.","i":"data:image/webp;base64,","c":"No machine-readable author provided. ArthurWeasley~commonswiki assumed · CC BY 2.5"},"Rhaeticosaurus":{"n":"Rhaeticosaurus","u":"https://dinosaurpictures.org/Rhaeticosaurus-pictures","r":"","p":"","z":"","g":"","t":"Rhaeticosaurus est un genre fossile de Plesiosauria basal des roches du Trias supérieur (Rhétien) de la formation Exter (en) en Allemagne. Le genre Rhaeticosaurus est resté monotypique et la seule espèce fossile est l'espèce type Rhaeticosaurus mertensi.","i":"data:image/webp;base64,","c":"Thomas P. Vida, Jürgen Kriwet and Thomas Martin · CC BY 4.0"},"Richardoestesia":{"n":"Richardoestesia","u":"https://dinosaurpictures.org/Richardoestesia-pictures","r":"carnivore","p":"Crétacé","z":"Amérique du Nord","g":"Navoiy Region (Uzbekistan), South Dakota et Chiapas (Mexique)","t":"Richardoestesia est un genre fossile de dinosaures théropodes paraviens de la famille des Dromaeosauridae dont les premiers fossiles ont été trouvés en Amérique du Nord datant du Crétacé supérieur. Ce genre Richardoestesia regroupe trois espèces : Richardoestesia asiatica Richardoestesia gilmorei et Richardoestesia isosceles.","i":"data:image/webp;base64,","c":"Derek W. Larson, Philip J. Currie · CC BY 2.5"},"Sachicasaurus":{"n":"Sachicasaurus","u":"https://dinosaurpictures.org/Sachicasaurus-pictures","r":"","p":"","z":"","g":"","t":"Sachicasaurus est un genre fossile de pliosaures de la sous-famille des Brachaucheninae connu du Barrémien de la formation de Paja, Cundiboyacense Altiplano dans les chaînes orientales colombiennes des Andes. Selon Paleobiology Database en 2025, ce genre est resté monotypique et l'espèce type et seule espèce est Sachicasaurus…","i":"data:image/webp;base64,","c":"María Páramo et al., 2018. Earth Sciences Research Journal, formerly G · CC BY 4.0"},"Sasayamagnomus":{"n":"Sasayamagnomus","u":"https://dinosaurpictures.org/Sasayamagnomus-pictures","r":"herbivore","p":"Crétacé inférieur","z":"Asia and North America","g":"Japon","t":"Sasayamagnomus est un genre fossile de dinosaures ornithischiens Marginocephalia du clade des Neoceratopsia. Ce genre est resté monotypique et la seule espèce fossile connue est l'espèce type Sasayamagnomus saegusai.","i":"data:image/webp;base64,","c":"Palaeotaku · CC BY 4.0"},"Saurornitholestes":{"n":"Saurornitholestes","u":"https://dinosaurpictures.org/Saurornitholestes-pictures","r":"carnivore","p":"Crétacé","z":"Amérique du Nord","g":"South Carolina, Coahuila (Mexique) et Heilongjiang (Chine)","t":"Saurornitholestes est un genre fossile de petits dinosaures maniraptoriens de la famille des Dromaeosauridae. Ils ont vécu en Amérique du Nord à la fin du Crétacé supérieur.","i":"data:image/webp;base64,","c":"Ferahgo the Assassin (Emily Willoughby, e.deinonychus@gmail.com) http: · CC BY 3.0"},"Scipionyx":{"n":"Scipionyx","u":"https://dinosaurpictures.org/Scipionyx-pictures","r":"carnivore","p":"Crétacé","z":"Europe","g":"Benevento (Italie)","t":"Scipionyx est un genre fossile de petits dinosaures théropodes de la famille des compsognathidés. Il a été découvert dans les calcaires lithographiques à silex de l'Albien inférieur (Crétacé), âgés d'environ 113 à 109 millions d'années, de la région de Pietraroja en Campanie dans le sud de l'Italie.","i":"data:image/webp;base64,","c":"Conty · CC BY 3.0"},"Shantungosaurus":{"n":"Shantungosaurus","u":"https://dinosaurpictures.org/Shantungosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Hebei (Chine), Jiangsu (Chine) et Shaanxi (Chine)","t":"Shantungosaurus est un genre éteint de grands dinosaures herbivores « à bec de canard » du sous-ordre des ornithopodes et de la famille des hadrosauridés. Ses fossiles ont été découverts en Chine dans la province de Shandong, dans un intervalle stratigraphique allant de l'extrême sommet de la formation géologique de Xingezhuang…","i":"data:image/webp;base64,","c":"Vitsuha · CC0"},"Siamodon":{"n":"Siamodon","u":"https://dinosaurpictures.org/Siamodon-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Siamraptor":{"n":"Siamraptor","u":"https://dinosaurpictures.org/Siamraptor-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Simolestes":{"n":"Simolestes","u":"https://dinosaurpictures.org/Simolestes-pictures","r":"","p":"","z":"","g":"","t":"","i":"data:image/webp;base64,","c":"Dmitry Bogdanov · CC BY-SA 3.0"},"Sirindhorna":{"n":"Sirindhorna","u":"https://dinosaurpictures.org/Sirindhorna-pictures","r":"herbivore","p":"Crétacé inférieur","z":"Asie","g":"Thailand","t":"Sirindhorna est un genre fossile de dinosaures ornithopodes de la super-famille des Hadrosauroidea, qui vivaient durant le Crétacé inférieur, probablement durant l'Aptien, soit il y a environ entre 121,4 et 113,2 millions d'années.","i":"data:image/webp;base64,","c":"Palaeotaku · CC BY 4.0"},"Spinosaurus":{"n":"Spinosaurus","u":"https://dinosaurpictures.org/Spinosaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"","c":""},"Struthiosaurus":{"n":"Struthiosaurus","u":"https://dinosaurpictures.org/Struthiosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Europe","g":"Roumanie, Barcelona (Espagne) et Rioja (Espagne)","t":"Struthiosaurus est un genre fossile de dinosaures ornithischiens herbivores, un ankylosaurien de la famille des nodosauridés qui vivait en Europe à la fin du Crétacé supérieur. Il est rattaché à la sous-famille des struthiosaurinés, à laquelle il a donné son nom, par James I.","i":"data:image/webp;base64,","c":"Ghedoghedo · CC BY-SA 3.0"},"Tambatitanis":{"n":"Tambatitanis","u":"https://dinosaurpictures.org/Tambatitanis-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Hyogo Prefecture (Japon)","t":"Tambatitanis est un genre fossile de dinosaures titanosauriformes du Crétacé inférieur du Japon. Il n'est connu que d'une seule espèce, son espèce type, Tambatitanis amicitiae, dont les restes fossiles ont été découverts dans la formation inférieure du groupe Sasayama.","i":"data:image/webp;base64,","c":"J-H. Jang · CC BY-SA 4.0"},"Thecodontosaurus":{"n":"Thecodontosaurus","u":"https://dinosaurpictures.org/Thecodontosaurus-pictures","r":"herbivore","p":"Trias","z":"Europe","g":"Bavaria (Allemagne), England (Royaume-Uni) et Matabeleland North (Zimbabwe)","t":"Thecodontosaurus est un genre fossile de dinosaures sauropodomorphes basaux, herbivores, qui vivait durant la fin du Trias supérieur.","i":"data:image/webp;base64,","c":"No machine-readable author provided. ArthurWeasley~commonswiki assumed · CC BY 2.5"},"Timimus":{"n":"Timimus","u":"https://dinosaurpictures.org/Timimus-pictures","r":"omnivore","p":"Crétacé","z":"Australie","g":"Victoria (australia)","t":"Timimus est un genre fossile de petits dinosaures théropodes ayant vécu en Australie à l'Albien (Crétacé inférieur. Les restes fossiles de l'animal consistent en deux fémurs appartenant l'un à un adulte, l'autre à un juvénile.","i":"data:image/webp;base64,","c":"Roger B. J. Benson1,2*, Thomas H. Rich3,4, Patricia Vickers-Rich3,4, M · CC BY 2.5"},"Torvosaurus":{"n":"Torvosaurus","u":"https://dinosaurpictures.org/Torvosaurus-pictures","r":"carnivore","p":"Jurassique","z":"Europe and North America","g":"Colorado, Colorado et Wyoming","t":"Torvosaurus est un genre fossile de dinosaures théropodes carnivores appartenant au clade des Megalosauridae et ayant vécu au Kimméridgien-Tithonien dans ce qui est actuellement l'Amérique du Nord et le Portugal.","i":"data:image/webp;base64,","c":"Fred Wierum · CC BY-SA 4.0"},"Trimucrodon":{"n":"Trimucrodon","u":"https://dinosaurpictures.org/Trimucrodon-pictures","r":"herbivore","p":"Jurassique","z":"Europe","g":"Área Metropolitana de Lisboa (Portugal)","t":"Trimucodon est un genre fossile d'ornithopodes découvert au Portugal. Une seule espèce est connue, Trimucrodon cuneatus.","i":"","c":""},"Streptospondylus":{"n":"Streptospondylus","u":"https://dinosaurpictures.org/Streptospondylus-pictures","r":"carnivore","p":"Jurassique","z":"Europe","g":"Normandy (France)","t":"Streptospondylus est un genre fossile de dinosaures théropodes du Jurassique retrouvé en France. L'espèce-type, Streptospondylus altdorfensis, a été décrite par Christian Erich Hermann von Meyer en 1832.","i":"data:image/webp;base64,","c":"Ghedoghedo · CC BY-SA 3.0"},"Titanosaurus":{"n":"Titanosaurus","u":"https://dinosaurpictures.org/Titanosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Inde","g":"Roumanie, Argentine et Aude (France)","t":"Titanosaurus est un genre fossile de dinosaure sauropode dont l'espèce Titanosaurus blanfordi Lydekker, 1879 a vécu, notamment en Inde, durant le Crétacé supérieur il y a environ 70 millions d'années.","i":"data:image/webp;base64,","c":"Lydekker · Public domain"},"Tuarangisaurus":{"n":"Tuarangisaurus","u":"https://dinosaurpictures.org/Tuarangisaurus-pictures","r":"","p":"","z":"","g":"","t":"Tuarangisaurus est un genre fossile d'élasmosauridés connus de Nouvelle-Zélande. Le type et la seule espèce connue est Tuarangisaurus keyesi, nommée en 1986 par Joan Wiffen et William L.","i":"data:image/webp;base64,","c":"FunkMonk · CC BY 3.0"},"Traskasaura":{"n":"Traskasaura","u":"https://dinosaurpictures.org/Traskasaura-pictures","r":"","p":"","z":"","g":"","t":"Traskasaura est un genre fossile de plésiosaures de la famille des Elasmosauridae. Le genre Traskasaura est resté monotypique et la seule espèce fossile référencée est l'espèce type Traskasaura sandrae.","i":"data:image/webp;base64,","c":"D. Gordon E. Robertson · CC BY-SA 3.0"},"Wannanosaurus":{"n":"Wannanosaurus","u":"https://dinosaurpictures.org/Wannanosaurus-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Jiangxi (Chine)","t":"Wannanosaurus est un genre fossile de tout petits dinosaures pachycéphalosaures du Crétacé supérieur (Campanien), soit il y a environ 80 Ma. Il a été découvert dans la formation de Xiaoyan en Chine, province de l'Anhui, région du Wannan.","i":"data:image/webp;base64,","c":"Jack Mayer Wood · CC BY-SA 4.0"},"Westphaliasaurus":{"n":"Westphaliasaurus","u":"https://dinosaurpictures.org/Westphaliasaurus-pictures","r":"","p":"","z":"","g":"","t":"","i":"data:image/webp;base64,","c":"Benson RBJ, Evans M, Smith AS, Sassoon J, Moore-Faye S, et al. · CC BY 2.5"},"Yanbeilong":{"n":"Yanbeilong","u":"https://dinosaurpictures.org/Yanbeilong-pictures","r":"herbivore","p":"Crétacé inférieur","z":"Asie","g":"Shanxi (Chine)","t":"Yanbeilong est un genre fossile de dinosaures ornithischiens, de la famille des Stégosauridés. On n'en connaît que l'espèce Yanbeilong ultimus, qui a vécu au Crétacé inférieur, il y a environ 113 à 100 millions d'années, dans ce qui est aujourd’hui la Chine.","i":"data:image/webp;base64,","c":"Wikimedia Commons"},"Yunganglong":{"n":"Yunganglong","u":"https://dinosaurpictures.org/Yunganglong-pictures","r":"herbivore","p":"Crétacé","z":"Asie","g":"Inner Mongolie (Chine)","t":"Yunganglong est un genre fossile de dinosaures Hadrosauroidea basal connu du début de la formation de Zhumapu (en) inférieur du Crétacé supérieur du comté de Zuoyun, dans la province du Shanxi, dans le nord-est de la Chine. Ce genre Yunganglong est resté monotypique et une seule espèce fossile est connue Yunganglong datongensis.","i":"data:image/webp;base64,","c":"Run-Fu Wang, Hai-Lu You, Shi-Chao Xu, Suo-Zhu Wang, Jian Yi, Li-Juan X · CC BY 2.5"},"Zby":{"n":"Zby","u":"https://dinosaurpictures.org/Zby-pictures","r":"herbivore","p":"Jurassique","z":"Europe","g":"Área Metropolitana de Lisboa (Portugal)","t":"Zby est un genre fossile de dinosaures sauropodes herbivores géants, appartenant au clade des Turiasauria. Il a vécu du Jurassique supérieur soit environ −153 Ma, et a été retrouvé dans la formation de Lourinhã, au Portugal.","i":"data:image/webp;base64,","c":"Levi bernardo · CC BY-SA 3.0"},"Zuoyunlong":{"n":"Zuoyunlong","u":"https://dinosaurpictures.org/Zuoyunlong-pictures","r":"herbivore","p":"Crétacé supérieur","z":"Asie","g":"Shanxi (Chine)","t":"Zuoyunlong est un genre fossile de dinosaures herbivores ornithopodes de la super-famille des Hadrosauroidea qui vivait au Cénomanien, il y a environ 95 millions d'années. Les restes fossiles de Zuoyunlong ont été retrouvés dans le xian de Zuoyun de la province chinoise du Shanxi.","i":"data:image/webp;base64,","c":"Miracusaurs · CC BY-SA 4.0"}};
